import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Rust → Handl cheat-sheet","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/notes/rust-to-handl.md","filePath":"vendored/handl/project/notes/rust-to-handl.md"}`),a={name:`handl/project/notes/rust-to-handl.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="rust-→-handl-cheat-sheet" tabindex="-1">Rust → Handl cheat-sheet <a class="header-anchor" href="#rust-→-handl-cheat-sheet" aria-label="Permalink to “Rust → Handl cheat-sheet”">​</a></h1><p>Reference for porting Rust code to idiomatic handl. Lookup tables first, idiom rules after. For <em>why</em> the seams exist, see ADR-0044/0077/0083/0096.</p><h2 id="what-stays-rust" tabindex="-1">What stays Rust <a class="header-anchor" href="#what-stays-rust" aria-label="Permalink to “What stays Rust”">​</a></h2><p>Only the calculus vocabulary and irreducible atoms: combinators, effect ops (<code>cap</code>/<code>op</code> + <code>handle ... with rust_*</code> natives — the host/FFI seam, <em>not</em> the abstraction mechanism), FFI marshalling primitives. Everything else — including interfaces to those atoms — is handl.</p><h2 id="construct-map" tabindex="-1">Construct map <a class="header-anchor" href="#construct-map" aria-label="Permalink to “Construct map”">​</a></h2><table tabindex="0"><thead><tr><th>Rust</th><th>Handl</th><th>Example</th></tr></thead><tbody><tr><td><code>fn f(x: T) -&gt; U</code></td><td><code>export f: T ~&gt; U := (x) ~&gt; expr</code></td><td><code>export now_ms: NowMs := () ~&gt; do { ... }</code></td></tr><tr><td><code>struct</code></td><td>record type</td><td><code>Timespec := { tv_sec: Int, tv_nsec: Int }</code></td></tr><tr><td><code>enum</code> (ADTs)</td><td><code>tag.tag(&quot;Name&quot;, payload)</code> + <code>tag.tag_of</code>/<code>untag</code>/<code>match_type</code>; prefer <code>option</code>/<code>result</code> packages</td><td><code>tag.tag(&quot;Some&quot;, { value: v })</code></td></tr><tr><td><code>Option&lt;T&gt;</code></td><td><code>from &quot;option&quot; import { some, none }</code> — a handl pkg, must be imported</td><td><code>option.test.hnl</code></td></tr><tr><td><code>Result&lt;T,E&gt;</code> / <code>?</code></td><td><code>from &quot;result&quot; import { ok, err }</code> — type+ctors only; combinators (<code>map</code>/<code>and_then</code>) are a separate pkg</td><td><code>result.test.hnl</code></td></tr><tr><td>exceptions/<code>catch</code></td><td>none — errors are values. Consume via <code>match tag.tag_of(r) { &quot;ok&quot;: …, &quot;err&quot;: … }</code></td><td><code>tag.untag(r).value</code></td></tr><tr><td><code>match</code></td><td><code>match x { pat: expr, _: default }</code> — literals, binders, <code>[]</code>/<code>[h,...t]</code>, <code>{field: b}</code></td><td><code>examples/handl/match.hnl</code></td></tr><tr><td><code>if/else</code> stmt</td><td>expression <code>if c { a } else { b }</code></td><td>—</td></tr><tr><td><code>for</code>/iterators</td><td><code>for x in xs { body }</code> — imperative <em>surface</em>, lowers to <code>rec</code> in the arrow calculus</td><td><code>datetime/helpers.hnl</code></td></tr><tr><td><code>map</code>/<code>fold</code>/…</td><td><code>fn.map</code>, <code>fn.fold</code>, <code>collection.*</code>, or combinator graph</td><td><code>unicode-handl.hnl</code></td></tr><tr><td><code>while</code> loop</td><td><code>while {state} {step}</code> — step returns <code>{state: v}</code> (continue) or <code>return v</code>/<code>{out: v}</code> (done)</td><td><code>examples/handl/fibonacci.hnl</code></td></tr><tr><td>recursion</td><td><code>while</code>/<code>for</code> (preferred) or self-application <code>(self ~&gt; self(self, x))</code></td><td><code>examples/handl/destructure.hnl</code></td></tr><tr><td><code>mut</code> / <code>&amp;mut</code></td><td><code>:=</code> writeback in <code>for</code> bodies; state record threaded through <code>while</code>/<code>rec</code>; no aliasing</td><td><code>{ xs: xs, acc: acc }</code></td></tr><tr><td><code>panic!</code>/<code>unwrap</code></td><td><code>result.err(msg)</code> — fallible arrows return <code>Result</code>; no raise/throw in handl</td><td><code>generated/libc</code> adapters</td></tr><tr><td>trait + impls</td><td>type decl + a value of that type — <code>I := { f: T ~&gt; U }</code>, <code>impl: I := { f: ... }</code></td><td><code>unicode-handl.hnl</code>, <code>time-c</code></td></tr><tr><td>module/<code>impl</code> block</td><td><code>do { helpers := ...; { exported: fields } }</code> — module-as-record</td><td><code>unicode-handl.hnl</code></td></tr><tr><td><code>cargo test</code></td><td><code>*.test.hnl</code> + <code>hnl test</code>; <code>test_name := assert expr</code></td><td><code>option/option.test.hnl</code></td></tr><tr><td>dep in Cargo.toml</td><td><code>.handl.toml</code> <code>[dependencies] name = { path = ... }</code></td><td>—</td></tr><tr><td><code>dlopen</code> FFI</td><td><code>ffi.call</code>/<code>ffi.bind</code>/<code>ffi.errno</code> + <code>types/c</code> aliases</td><td><code>generated/libc/*.hnl</code></td></tr></tbody></table><h2 id="bindings-and-syntax-quick-ref" tabindex="-1">Bindings and syntax quick-ref <a class="header-anchor" href="#bindings-and-syntax-quick-ref" aria-label="Permalink to “Bindings and syntax quick-ref”">​</a></h2><div class="language-hnl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">hnl</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>export f: T ~&gt; U := (x) ~&gt; expr   -- top-level, typed</span></span>
<span class="line"><span>x := expr                         -- definition / binding (top level, do, for-body)</span></span>
<span class="line"><span>a == b                            -- equality (= / :: assigns are legacy</span></span>
<span class="line"><span>                                  -- spellings, being removed from grammar)</span></span>
<span class="line"><span>do { a := f(); b := g(a); a + b } -- sequential block; last expr is value</span></span>
<span class="line"><span>for x in xs { acc := f(acc, x) }  -- imperative sugar → rec lowering;</span></span>
<span class="line"><span>                                  -- := writes back to enclosing scope;</span></span>
<span class="line"><span>                                  -- the for expression itself is []</span></span>
<span class="line"><span>while { n: 5, acc: 1 } {          -- stateful loop: init record, step arrow</span></span>
<span class="line"><span>  [n, acc] ~&gt; if n == 0</span></span>
<span class="line"><span>    return acc</span></span>
<span class="line"><span>  else { { state: { n: n-1, acc: acc*n } } }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>arr(&quot;list.tail&quot;) &gt;&gt;&gt; first(id)    -- combinator style (calculus vocabulary)</span></span>
<span class="line"><span>rec { ... }                       -- fixpoint region (state machines)</span></span>
<span class="line"><span>from &quot;m&quot; import { a, b }          -- named</span></span>
<span class="line"><span>from &quot;m&quot; import * as m            -- namespace → m.f(...)</span></span>
<span class="line"><span>-- ALWAYS import. Bare \`mod.f\` resolution (tag, error, str, …) is a</span></span>
<span class="line"><span>-- legacy fallback slated for removal — corpus uses it, new code must not.</span></span>
<span class="line"><span>handle arr f with Mod             -- effect injection — host/native ops only</span></span>
<span class="line"><span>                                  -- (see time-c); NOT the trait/impl idiom</span></span></code></pre></div><h2 id="ffi-descriptor-map-adr-0083" tabindex="-1">FFI descriptor map (ADR-0083) <a class="header-anchor" href="#ffi-descriptor-map-adr-0083" aria-label="Permalink to “FFI descriptor map (ADR-0083)”">​</a></h2><table tabindex="0"><thead><tr><th>C type</th><th>Descriptor</th><th>Handl arg</th></tr></thead><tbody><tr><td><code>int32_t</code>, <code>int64_t</code>, <code>double</code></td><td><code>&quot;i32&quot;</code> <code>&quot;i64&quot;</code> <code>&quot;f64&quot;</code></td><td>number</td></tr><tr><td><code>const char *</code></td><td><code>&quot;cstr&quot;</code></td><td>string (UTF-8, no NUL)</td></tr><tr><td><code>void *</code></td><td><code>&quot;ptr&quot;</code> / <code>&quot;handle&quot;</code></td><td>number / <code>{__resource__:{ptr:N}}</code></td></tr><tr><td><code>const void * + size_t</code></td><td><code>&quot;in_buf&quot;</code> / <code>&quot;cbytes&quot;</code></td><td>Bytes</td></tr><tr><td><code>void * + size_t</code> out</td><td><code>&quot;out_buf:N&quot;</code></td><td>— → <code>{ret, buf}</code></td></tr><tr><td><code>void *</code> out (fixed)</td><td><code>&quot;out_ptr:N&quot;</code></td><td>— → <code>{ret, buf}</code></td></tr><tr><td><code>T *</code> value-result</td><td><code>&quot;io_buf:N&quot;</code> <code>&quot;io_scalar:T&quot;</code></td><td>— / seed</td></tr><tr><td><code>const T *</code> / <code>T *</code></td><td><code>&quot;in_struct:{…}&quot;</code> <code>&quot;io_struct:{…}&quot;</code> <code>&quot;out_struct:{…}&quot;</code></td><td>record / —</td></tr><tr><td><code>void</code> ret</td><td><code>&quot;void&quot;</code></td><td>→ null</td></tr></tbody></table><p>Bytes are <code>{&quot;__bytes__&quot;: [n, ...]}</code>; plain arrays also accepted on input. <code>errno</code> flag on <code>ffi.call</code> maps negative returns to <code>errno</code> extraction — wrap in <code>result.err</code> at the adapter edge (see <code>generated/libc</code>).</p><blockquote><p><strong>Gap:</strong> <code>ffi.call</code> <em>raises</em> on <code>dlopen</code>/<code>dlsym</code> failure — incompatible with the Result-only error model. A non-raising probe op (<code>ffi.load</code> / <code>ffi.sym</code> returning <code>Result</code> or <code>Option</code>) is needed before handl-side library/symbol probing (e.g. ICU version sniffing) can be written idiomatically. <code>error.try</code> exists as a host atom but is not the idiom.</p></blockquote><h2 id="idiom-rules" tabindex="-1">Idiom rules <a class="header-anchor" href="#idiom-rules" aria-label="Permalink to “Idiom rules”">​</a></h2><ol><li><strong>Contract = a type; impl = a value of that type.</strong> Declare the interface as a record/arrow type (<code>I := { f: T ~&gt; U, ... }</code>, plus <code>axiom</code>/<code>guarantee:</code> laws where refinement matters) in a neutral package; a backend (<code>name-handl</code> / <code>name-c</code> / <code>name-native</code> / <code>name-stub</code>) exports a value of that type — usually a <code>do { ...; { f: impl } }</code> record. Callers pick the backend by import path (<code>from &quot;time-c&quot; import { now_ms }</code>). <code>cap</code>/<code>op</code>/<code>handle ... with</code> are for <em>effects</em> (host/FFI ops), never for trait-style abstraction.</li><li><strong>Errors are values — no raise/throw.</strong> Fallible arrows return <code>Result&lt;T, E&gt;</code>; <code>error.raise</code>/<code>error.try</code> are host atoms for runtime internals, not the handl idiom (legacy corpus usage like <code>collections/*.hnl</code> <code>pop</code> is slated to move).</li><li><strong>Fail loudly, never approximate.</strong> If a backend can&#39;t implement an op correctly, omit it — callers get a loud failure (<code>unicode-handl</code> omits <code>nfc</code>/<code>nfd</code> rather than shipping identity).</li><li><strong>Semantic names, not implementation names</strong> — <code>nfc</code>, never <code>nfc_icu4x</code>; <code>graphemes</code>, never <code>graphemes_utf16</code>.</li><li><strong>Effects are inferred, not annotated</strong> — effectfulness comes from the <code>cap</code>/<code>op</code> declaration, not the signature. <code>~[N]~&gt;</code> is an arrow <em>dimension</em> annotation (ADR-0119), not an effect row — don&#39;t write it for effect marking.</li><li><strong><code>for</code> for iteration, <code>while</code> for stateful loops</strong> — <code>for x in xs</code> when you&#39;re walking a list; <code>while {state} {step}</code> when the loop is a state machine or terminates on a condition. Avoid self-application recursion.</li><li><strong>Docs are <code>---</code> + <code>@details</code>/<code>@param</code>/<code>@returns</code>/<code>@example</code></strong></li><li><strong>Marshal at the edge.</strong> Convert <code>Bytes</code>/handles/<code>{ret,buf,outs}</code> into semantic handl types inside the backend — never leak C shapes upward.</li></ol><h2 id="port-checklist" tabindex="-1">Port checklist <a class="header-anchor" href="#port-checklist" aria-label="Permalink to “Port checklist”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> contract package exists or is written (types + laws)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> backend package <code>name-c</code>/<code>name-handl</code> exports the contract record</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"><code>---</code> headers + <code>@details</code>/<code>@param</code>/<code>@returns</code>/<code>@example</code></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"><code>*.test.hnl</code> covering each export; FFI-dependent tests gate on library availability (see FFI gap note)</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"><code>hnl fmt --check &amp;&amp; hnl lint &amp;&amp; hnl typecheck &amp;&amp; hnl test</code> green (<code>scripts/dogfood-gate.sh</code>)</label></li></ul>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};